const tbl=(labels,rows)=>`<div class="tablebox" style="max-width:420px">${seqTable({rows},labels,-1)}</div>`;
const g17=k=>genSeq(MOT.q17,k),g18=k=>genSeq(MOT.q18,k),g110=k=>genSeq(MOT.f116,k);
